template.xpath:
.subir-comp h3{margin:1rem 0 .2rem;font-size:.95rem}
.subir-comp form{margin:0}
.subir-comp label{display:block;font-size:.8rem;color:var(--tenue);margin:.6rem 0 .2rem}
.subir-comp input[type=file]{width:100%;font:inherit;font-size:.9rem;padding:.5rem;
                             border:1px dashed var(--linea);border-radius:6px;background:#fafafa}
.subir-comp input[type=text]{width:100%;max-width:14rem;font:inherit;padding:.55rem .7rem;
                             border:1px solid var(--linea);border-radius:6px}
.subir-comp .subir{display:block;width:100%;max-width:22rem;margin:.9rem 0 0;background:var(--acento);
                   color:#fff;border:0;border-radius:6px;padding:.85rem 1.2rem;font:inherit;
                   font-weight:700;cursor:pointer}
.subir-comp .subir:disabled{opacity:.6}
.subir-comp .ok-comp{background:#d3f9d8;color:#2b8a3e;font-weight:700;border-radius:6px;
                     padding:.6rem .8rem;margin:0 0 .8rem}
.subir-comp .error-comp{background:#ffe3e3;color:var(--alerta);font-weight:600;border-radius:6px;
                        padding:.6rem .8rem;margin:0 0 .8rem}
.subir-comp .fila-comp{display:flex;justify-content:space-between;align-items:center;gap:.8rem;
                       padding:.6rem 0;border-top:1px solid var(--borde);font-size:.88rem}
.subir-comp .fila-comp .nom{font-weight:600;word-break:break-all}
.subir-comp .estado-comp{flex:none;font-size:.75rem;border-radius:99px;padding:.15rem .6rem;
                         background:#fff3bf;color:var(--aviso);font-weight:600}
.subir-comp .estado-comp.aprobado{background:#d3f9d8;color:#2b8a3e}
.subir-comp .estado-comp.rechazado{background:#ffe3e3;color:var(--alerta)}
.subir-comp .estado-comp.cerrado,.subir-comp .estado-comp.repetido{background:#eee;color:var(--tenue)}

xpath.script:
(function () {
  // the same limits as the server: a 20 MB photo is refused here
  // before it is sent over the phone's data
  var form = document.getElementById('form-subir-comprobante');
  if (!form) { return; }
  var max = 10 * 1024 * 1024, tipos = ['image/jpeg', 'image/png', 'image/webp', 'application/pdf'];
  function aviso(texto) {
    var p = form.parentNode.querySelector('.error-comp, .ok-comp');
    if (!p) {
      p = document.createElement('p');
      form.parentNode.insertBefore(p, form.parentNode.querySelector('h2').nextSibling);
    }
    p.className = 'error-comp';
    p.setAttribute('role', 'status');
    p.textContent = texto;
  }
  form.addEventListener('submit', function (ev) {
    var f = form.querySelector('input[type=file]').files[0];
    if (!f) { return; }
    if (f.size > max) {
      ev.preventDefault();
      aviso('El archivo pesa más de 10 MB. Mandá una captura o una foto más liviana.');
    } else if (f.type && tipos.indexOf(f.type) < 0) {
      ev.preventDefault();
      aviso('Subí una foto (JPG, PNG o WEBP) o un PDF del comprobante.');
    }
  });
})();
